use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // Read the configured feed list from the one store this node may read.
        // Entries are stored one URL per line; blank lines are ignored.
        let mut urls: Vec<String> = match state_read::get("subscriptions") {
            Some(blob) => blob
                .lines()
                .map(|line| line.trim())
                .filter(|line| !line.is_empty())
                .map(|line| line.to_string())
                .collect(),
            None => Vec::new(),
        };

        // `ensures present(urls)`: never hand back an empty list. If the store
        // is unset or empty, fall back to a single built-in default so the
        // output always has at least one URL.
        if urls.is_empty() {
            urls.push("https://blog.rust-lang.org/feed.xml".to_string());
        }

        SubscriptionList { urls }
    }
}

export!(Node);
