use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored. The store cannot be
/// enumerated, so we ask about the names we know, in order.
const KEYS: &[&str] = &["subscriptions", "urls", "feeds", "subscription-list"];

/// Used only if the store holds nothing usable. Every host here is on the
/// downstream fetch allowlist, so the fallback never asks for authority the
/// graph did not grant.
const FALLBACK: &[&str] = &[
    "https://simonwillison.net/atom/everything/",
    "https://lobste.rs/rss",
];

/// Extract the string literals from a JSON array of strings.
fn parse_json_strings(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut cur = String::new();
        while let Some(c) = chars.next() {
            match c {
                '"' => break,
                '\\' => match chars.next() {
                    Some('n') => cur.push('\n'),
                    Some('t') => cur.push('\t'),
                    Some('r') => cur.push('\r'),
                    Some('/') => cur.push('/'),
                    Some('\\') => cur.push('\\'),
                    Some('"') => cur.push('"'),
                    Some(other) => cur.push(other),
                    None => break,
                },
                other => cur.push(other),
            }
        }
        out.push(cur);
    }
    out
}

fn parse_blob(blob: &str) -> Vec<String> {
    let trimmed = blob.trim();
    let raw: Vec<String> = if trimmed.starts_with('[') {
        parse_json_strings(trimmed)
    } else {
        trimmed
            .split(|c: char| c == '\n' || c == ',' || c.is_whitespace())
            .map(|s| s.to_string())
            .collect()
    };

    let mut urls: Vec<String> = Vec::new();
    for item in raw {
        let u = item.trim().trim_matches('"').trim();
        if (u.starts_with("https://") || u.starts_with("http://"))
            && !urls.iter().any(|x| x == u)
        {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in KEYS {
            if let Some(blob) = state_read::get(key) {
                let parsed = parse_blob(&blob);
                if !parsed.is_empty() {
                    urls = parsed;
                    break;
                }
            }
        }

        // `ensures present(urls)`: never return an empty list.
        if urls.is_empty() {
            urls = FALLBACK.iter().map(|s| s.to_string()).collect();
        }

        SubscriptionList { urls }
    }
}

export!(Node);
